const levels=[
 {name:'Gentle Garden',zh:'柔音花園',size:3,target:'soft',goal:8,time:70,stay:2300},
 {name:'Greenhouse Gate',zh:'溫室大門',size:4,target:'hard',goal:10,time:75,stay:2000},
 {name:'Grand Garden Festival',zh:'花園慶典',size:5,target:'mixed',goal:12,time:90,stay:1700}
];
const words={
 soft:[['gem','core'],['gym','core'],['magic','core'],['age','core'],['page','core'],['cage','core'],['giraffe','regular'],['giant','regular'],['gentle','regular'],['orange','regular'],['bridge','challenge'],['stage','challenge'],['ginger','challenge'],['village','challenge']],
 hard:[['gum','core'],['gate','core'],['pig','core'],['mug','core'],['game','core'],['dog','core'],['bag','core'],['goat','regular'],['garden','regular'],['green','regular'],['frog','regular'],['egg','regular'],['glove','challenge'],['hungry','challenge'],['penguin','challenge'],['kangaroo','challenge']]
};
const tierWeights=[[.80,.15,.05],[.70,.20,.10],[.60,.25,.15]],tiers=['core','regular','challenge'];
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const screens=$$('.screen'),tutorial=$('#tutorial'),pauseModal=$('#pause-modal'),bgm=$('#bgm');bgm.volume=.22;
const sounds={swing:$('#sfx-swing'),hit:$('#sfx-hit'),score:$('#sfx-score'),hurt:$('#sfx-hurt'),cheer:$('#sfx-cheer')};Object.values(sounds).forEach(a=>a.volume=.72);
let bgmOn=true,sfxOn=true,currentLevel=0,score=0,lives=5,timeLeft=0,total=0,correctAnswers=0,listens=0,spawnCount=0,timerId=null,spawnId=null,activeHole=null,paused=false,running=false,currentTarget='soft',spawnDeadline=0,unlocked=Math.max(0,Math.min(2,Number(localStorage.getItem('gGardenUnlocked')||0)));
function showScreen(id){screens.forEach(s=>s.classList.toggle('active',s.id===id))}
function playSfx(name,delay=0){if(!sfxOn)return;setTimeout(()=>{const a=sounds[name];a.currentTime=0;a.play().catch(()=>{})},delay)}
function speak(text,rate=.84){if(!('speechSynthesis'in window))return;speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='en-US';u.rate=rate;u.pitch=1.05;speechSynthesis.speak(u)}
function startBgm(){if(bgmOn)bgm.play().catch(()=>{})}
function syncAudioButtons(){$$('.bgm-toggle').forEach(b=>{b.classList.toggle('off',!bgmOn);b.textContent=bgmOn?'♫':'♩'});$$('.sfx-toggle').forEach(b=>{b.classList.toggle('off',!sfxOn);b.textContent=sfxOn?'🔊':'🔇'})}
function openTutorial(){tutorial.classList.add('open');tutorial.setAttribute('aria-hidden','false')}function closeTutorial(){tutorial.classList.remove('open');tutorial.setAttribute('aria-hidden','true')}
function renderMap(){$$('.level-card').forEach((b,i)=>{const ok=i<=unlocked;b.classList.toggle('unlocked',ok);b.disabled=!ok;const lock=b.querySelector('u');if(lock)lock.style.display=ok?'none':'block'});showScreen('map-screen');startBgm()}
function makeGrid(size){const grid=$('#garden-grid');grid.className=`garden-grid grid-${size}`;grid.innerHTML='';for(let i=0;i<size*size;i++){const hole=document.createElement('div');hole.className='hole';hole.setAttribute('role','button');hole.tabIndex=0;hole.setAttribute('aria-label','Empty flowerpot');hole.innerHTML='<span class="sprout-wrap"><img class="sprout" src="assets/sprout-normal.png" alt=""><span class="word-card"></span><button type="button" class="word-audio" aria-label="Listen to word" disabled tabindex="-1">🔊</button></span>';hole.addEventListener('click',e=>{if(e.target.classList.contains('word-audio')){e.stopPropagation();listenWord(hole);return}whack(hole,e)});hole.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target===hole){e.preventDefault();whack(hole,{clientX:innerWidth/2,clientY:innerHeight/2})}});grid.appendChild(hole)}}
function setTarget(type){currentTarget=type;const label=$('#target-label');label.textContent=type==='soft'?'SOFT G /dʒ/':'HARD G /g/';label.style.color=type==='soft'?'#179f86':'#c76920';$('#mission-zh').textContent=type==='soft'?'找出發 /dʒ/ 的 soft g 單字':'找出發 /g/ 的 hard g 單字'}
function startLevel(index){currentLevel=index;const l=levels[index];score=0;lives=5;timeLeft=l.time;total=0;correctAnswers=0;listens=0;spawnCount=0;paused=false;running=true;makeGrid(l.size);setTarget(l.target==='mixed'?(Math.random()<.5?'soft':'hard'):l.target);$('#stage-label').textContent=`STAGE ${index+1} · ${l.size}×${l.size} · ${l.name.toUpperCase()}`;$('#goal-value').textContent=l.goal;updateHud();showScreen('game-screen');startBgm();clearInterval(timerId);timerId=setInterval(()=>{if(!paused&&running){timeLeft--;updateHud();if(timeLeft<=0)endLevel(false)}},1000);clearTimeout(spawnId);scheduleSpawn(500)}
function updateHud(){$('#score-value').textContent=score;$('#time-value').textContent=timeLeft;$('#hearts').textContent=currentLevel<2?'PRACTICE｜練習模式':[0,1,2,3,4].map(i=>i<lives?'♥':'♡').join(' ')}
function chooseWord(type){const w=tierWeights[currentLevel],r=Math.random();const tier=spawnCount<3?'core':r<w[0]?tiers[0]:r<w[0]+w[1]?tiers[1]:tiers[2];const pool=words[type].filter(x=>x[1]===tier);spawnCount++;return pool[Math.floor(Math.random()*pool.length)]}
function scheduleSpawn(delay=650){clearTimeout(spawnId);spawnId=setTimeout(spawnMole,delay)}
function spawnMole(){if(!running||paused)return;if(activeHole)hideMole(activeHole);if(levels[currentLevel].target==='mixed')setTarget(Math.random()<.5?'soft':'hard');const holes=$$('.hole'),hole=holes[Math.floor(Math.random()*holes.length)],isTarget=Math.random()<.62,type=isTarget?currentTarget:(currentTarget==='soft'?'hard':'soft'),[word,tier]=chooseWord(type);hole.dataset.word=word;hole.dataset.type=type;hole.dataset.tier=tier;hole.dataset.answered='false';hole.dataset.extended='false';hole.classList.toggle('challenge',tier==='challenge');hole.querySelector('.word-card').innerHTML=(tier==='challenge'?'✦ ':'')+highlightG(word);const listen=hole.querySelector('.word-audio');listen.disabled=false;listen.tabIndex=0;listen.classList.remove('extended');hole.setAttribute('aria-label',`${word}. Press to choose or use listen.`);hole.classList.add('active');activeHole=hole;const stay=levels[currentLevel].stay;spawnDeadline=performance.now()+stay;spawnId=setTimeout(expireActive,stay)}
function expireActive(){if(activeHole){hideMole(activeHole);scheduleSpawn(180)}}
function highlightG(word){const i=word.toLowerCase().indexOf('g');return i<0?word:`${word.slice(0,i)}<span class="g-letter">${word[i]}</span>${word.slice(i+1)}`}
function listenWord(hole){if(!hole.dataset.word)return;listens++;speak(hole.dataset.word);if(hole.dataset.extended==='false'){hole.dataset.extended='true';const remain=Math.max(0,spawnDeadline-performance.now())+3000;clearTimeout(spawnId);spawnDeadline=performance.now()+remain;spawnId=setTimeout(expireActive,remain);const b=hole.querySelector('.word-audio');b.classList.remove('extended');void b.offsetWidth;b.classList.add('extended')}}
function hideMole(hole){hole.classList.remove('active','correct','wrong','challenge');hole.dataset.answered='true';delete hole.dataset.word;delete hole.dataset.type;delete hole.dataset.tier;hole.setAttribute('aria-label','Empty flowerpot');hole.querySelector('.word-card').textContent='';hole.querySelector('.sprout').src='assets/sprout-normal.png';const listen=hole.querySelector('.word-audio');listen.disabled=true;listen.tabIndex=-1;listen.classList.remove('extended');if(activeHole===hole)activeHole=null}
function wandAt(hole){const w=$('#wand'),sprout=hole.querySelector('.sprout'),r=sprout.getBoundingClientRect();const x=Math.min(innerWidth-42,Math.max(42,r.left+r.width*.64)),y=Math.min(innerHeight-42,Math.max(42,r.top+r.height*.38));w.style.left=`${x}px`;w.style.top=`${y}px`;w.classList.remove('swing');void w.offsetWidth;w.classList.add('swing');w.addEventListener('animationend',()=>w.classList.remove('swing'),{once:true})}
function showFeedback(good,word,type,tier){const f=$('#feedback');f.className=`feedback show ${good?'good':'bad'}`;f.innerHTML=good?`✓ ${tier==='challenge'?'Amazing challenge!':'Correct!'} <b>${word}</b><br><small>${tier==='challenge'?'挑戰成功！':'答對了！'}</small>`:`✕ <b>${word}</b> is ${type==='soft'?'soft G /dʒ/':'hard G /g/'}<br><small>聽一聽，再試一次！</small>`;setTimeout(()=>f.classList.remove('show'),1800)}
function whack(hole,e){if(!running||paused||!hole.classList.contains('active')||hole.dataset.answered==='true')return;hole.dataset.answered='true';wandAt(hole);playSfx('swing');const good=hole.dataset.type===currentTarget,tier=hole.dataset.tier,sprout=hole.querySelector('.sprout');total++;if(good){correctAnswers++;score+=tier==='challenge'?2:1;hole.classList.add('correct');sprout.src='assets/sprout-correct.png';playSfx('score',90);showFeedback(true,hole.dataset.word,hole.dataset.type,tier)}else{if(currentLevel===2&&tier!=='challenge')lives--;hole.classList.add('wrong');sprout.src='assets/sprout-hit.png';playSfx('hit',80);playSfx('hurt',180);showFeedback(false,hole.dataset.word,hole.dataset.type,tier)}updateHud();clearTimeout(spawnId);setTimeout(()=>{hideMole(hole);if(score>=levels[currentLevel].goal)endLevel(true);else if(currentLevel===2&&lives<=0)endLevel(false);else scheduleSpawn(220)},1800)}
function endLevel(success){if(!running)return;running=false;clearInterval(timerId);clearTimeout(spawnId);if(activeHole)hideMole(activeHole);const accuracy=total?Math.round(correctAnswers/total*100):0,stars=success?(accuracy>=90?3:accuracy>=70?2:1):0;$('#result-stars').textContent=stars?'★ '.repeat(stars).trim():'☆ ☆ ☆';$('#result-title').textContent=success?'Garden in Bloom!':"Let's Grow Again";$('#result-subtitle').textContent=success?'花園盛開了！':'再練習一次，你一定可以！';$('#result-score').textContent=`${score}/${levels[currentLevel].goal}`;$('#result-accuracy').textContent=`${accuracy}%`;$('#result-listens').textContent=listens;$('#result-sprout').src=success?'assets/sprout-correct.png':'assets/sprout-hit.png';if(success){playSfx('cheer');if(currentLevel<2){unlocked=Math.max(unlocked,currentLevel+1);localStorage.setItem('gGardenUnlocked',String(unlocked))}}$('#continue-btn span').textContent=success&&currentLevel<2?'Next Garden':'Garden Map';$('#continue-btn small').textContent=success&&currentLevel<2?'下一關':'花園地圖';showScreen('result-screen')}
function togglePause(force){if(!running)return;paused=force??!paused;pauseModal.classList.toggle('open',paused);pauseModal.setAttribute('aria-hidden',String(!paused));if(paused){clearTimeout(spawnId)}else scheduleSpawn(350)}
$('#start-btn').addEventListener('click',()=>{startBgm();openTutorial()});$('#how-btn').addEventListener('click',openTutorial);$('#tutorial-go').addEventListener('click',()=>{closeTutorial();renderMap()});$('.close').addEventListener('click',closeTutorial);$$('[data-action="home"]').forEach(b=>b.addEventListener('click',()=>showScreen('home-screen')));$$('[data-action="map"]').forEach(b=>b.addEventListener('click',()=>{running=false;clearInterval(timerId);clearTimeout(spawnId);renderMap()}));$$('.level-card').forEach((b,i)=>b.addEventListener('click',()=>{if(i<=unlocked)startLevel(i)}));$('#target-sound').addEventListener('click',()=>{listens++;speak(currentTarget==='soft'?'Soft G. The sound is juh, as in gem.':'Hard G. The sound is guh, as in gum.')});$('#pause-btn').addEventListener('click',()=>togglePause());$('#resume-btn').addEventListener('click',()=>togglePause(false));$$('.bgm-toggle').forEach(b=>b.addEventListener('click',()=>{bgmOn=!bgmOn;if(bgmOn)startBgm();else bgm.pause();syncAudioButtons()}));$$('.sfx-toggle').forEach(b=>b.addEventListener('click',()=>{sfxOn=!sfxOn;syncAudioButtons()}));$('#retry-btn').addEventListener('click',()=>startLevel(currentLevel));$('#continue-btn').addEventListener('click',()=>{if(score>=levels[currentLevel].goal&&currentLevel<2)startLevel(currentLevel+1);else renderMap()});syncAudioButtons();showScreen('home-screen');
